"""Record measured partial engineering outcome and immutable evidence."""
from pathlib import Path
from datetime import datetime,timezone
from collections import Counter
import json,hashlib,subprocess,ast,xml.etree.ElementTree as ET
R=Path('reports');P='search_proof4_';C=Path('scratch/search_proof_recovery_v4')
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def load(n):return json.loads((R/(P+n)).read_text(encoding='utf8'))
def write(n,v):
    with (R/(P+n)).open('x',encoding='utf8') as f:json.dump(v,f,indent=2,ensure_ascii=False,sort_keys=True)
def link(p):return '['+Path(p).name+']('+Path(p).resolve().as_posix()+')'
def doc(number,title,body):
    with (R/(P+str(number).zfill(2)+'_'+title+'.md')).open('x',encoding='utf8') as f:f.write('# '+title.replace('_',' ')+'\n\n'+body+'\n')
def main():
    pre=load('preflight.json');assert all(sha(p)==h for p,h in pre['protected_files'].items())
    config=load('c5c_recorded_parser_configuration.json');assert all(sha(p)==h for p,h in config['parser_source_hashes'].items())
    metrics={'C5C644':load('c5c_recorded_typed_decision_scoring.json')['overall']}
    for name in ['c5e90','c5er150','smarteng150','comp3_150']:metrics[name]=load('recorded_'+name+'_results.json')['summary']
    tests=ET.parse(R/(P+'recorded_tests.xml')).getroot();suite=next(tests.iter('testsuite'));failed=[]
    for t in tests.iter('testcase'):
        failure=t.find('failure');error=t.find('error')
        if failure is not None or error is not None:failed.append({'name':t.attrib['name'],'file':t.attrib.get('classname'),'message':(failure if failure is not None else error).attrib.get('message','')})
    focused=[t for t in tests.iter('testcase') if 'search_proof_recovery_v4' in t.attrib.get('classname','')]
    assert all(t.find('failure') is None and t.find('error') is None for t in focused)
    write('regression_failures.json',{'tests':suite.attrib,'focused_passed':len(focused),'remaining_failures':failed,'gold_edited':False,
        'categories':'Includes repair-provenance shape, source/intent/preference wire behavior, anecdote/role interpretation, trusted session edits, numeric conjunctions and native mutation proof compatibility. Exact individual messages retained; not all are cosmetic.'})
    perf=load('recorded_performance.json')['results'];native=load('certified_retrieval_contracts_final.json');edit=load('edit_audit.json')
    inventory=[];symbols=[]
    for p in C.glob('*.py'):
        inventory.append({'path':str(p),'sha256':sha(p),'lines':len(p.read_text(encoding='utf8').splitlines())})
        for n in ast.walk(ast.parse(p.read_text(encoding='utf8'))):
            if isinstance(n,(ast.FunctionDef,ast.ClassDef)):symbols.append({'path':str(p.resolve()),'symbol':n.name,'line':n.lineno})
    write('source_inventory.json',{'candidate_id':'search-smarteng-disabled-proof-4','source_files':inventory,'symbols':symbols,
        'lineage':'Derived from frozen V3 source ownership, numeric/format grammar and indexed vocabulary; plan construction/decision authority replaced. Source repairs and vocabulary reused; all production and frozen parent files unchanged.'})
    fallback=[{'path':'native.parse_query SMART','classification':'UNSUPPORTED_AND_UNSAFE_AS_AUTHORITY','action':'Removed from SMART compilation. Empty QueryPlan projected only from IR.'},
        {'path':'native.parse_query explicit literal/identifier modes','classification':'PROVEN_SAFE_UNDER_BOUNDED_CONTRACT','action':'Retained established literal modes and exact identifier behavior; scope remains external.'},
        {'path':'native._parse_legacy semantic residue','classification':'SEMANTICALLY_LOSSY','action':'Invoked with EMPTY vocabulary and constraints disabled, only for semantic/intent proposals. Never copies structured fields or decisions; semantic-string compatibility still incomplete.'},
        {'path':'native numeric/format/subject recognizers','classification':'SAFE_ONLY_WITH_SOURCE_EVIDENCE','action':'Proposals only. Original spans, canonical facts, values/operators and projection validated.'},
        {'path':'semantic_safety.finish inventory','classification':'SAFE_ONLY_AS_TYPED_EVIDENCE','action':'Its plan/decision discarded. Field-specific unresolved/unsupported/conflict evidence admitted upstream of final IR. Generic old residue guard disabled because only current IR owns completeness. Advisory and complete entity roles reconciled.'},
        {'path':'native decide/transform edits','classification':'UNSAFE_WHEN_PROOF_IS_DROPPED','action':'Candidate decide preserves contract/projection proof; validate rejects SMART plans without proof and mutated projections. correction_keep rejects422 until trusted source recompilation integration exists.'}]
    write('fallback_audit.json',fallback)
    NA={'status':'NOT_RUN','numerator':None,'denominator':0,'reason':'Development regression and native edit compatibility gates remain unsatisfied; no fresh population or primary capture was started.'}
    required={'FINAL':'PARTIAL','CANDIDATE_ID':'search-smarteng-disabled-proof-4','ARCHITECTURE_SELECTED':'Deterministic bounded source IR and pure execution proof; no learned component enabled.',
        'SOURCE_OWNERSHIP_VERIFIED':'PARTIAL: projection/source evidence tested, full natural-language extraction coverage not established.',
        'REQUIREMENT_LEDGER_COMPLETE':False,'UNSAFE_FALLBACKS_RESOLVED':'Legacy SMART hard-filter/decision authority removed; semantic residue and compatibility remain incomplete.',
        'MISSING_OPERAND_BEHAVIOR':'Explicit states, partial placeholders, sort slots and metalinguistic evidence; finite focused tests pass, broader role regressions remain.',
        'NEGATIVE_CONSTRAINT_BEHAVIOR':'Domain/polarity owned before scalar proposals; word-order metamorphisms and Marsh/ar pass; universal meaning coverage unproven.',
        'INVENTED_FACET_BEHAVIOR':'No legacy facet-plan copying; canonical source facts and projection replay required. Zero scored executed hard mismatches in recorded exposed cohorts.',
        'CANONICAL_REPAIR_BEHAVIOR':'Scoped bounded repairs and original source notices retained; legacy provenance/wire assertions still fail.',
        'DEVELOPMENT_TYPED_ACCURACY':{k:v['typed_accuracy'] for k,v in metrics.items()},'DEVELOPMENT_EXECUTION_ACCURACY':{k:v['execution_accuracy'] for k,v in metrics.items()},
        'INDEPENDENT_TYPED_ACCURACY':NA,'INDEPENDENT_EXECUTION_ACCURACY':NA,'INDEPENDENT_FALSE_EXECUTION':NA,'INDEPENDENT_MISSED_EXECUTION':NA,
        'MANDATORY_CONSTRAINT_LOSS':{'status':'No scored executed hard-operand mismatches in recorded exposed cohorts; strict semantic/provenance failures remain.','population_contexts':{'C5C':644,'C5E':90,'C5ER':150,'SmartEngineering':150,'Comp3':150}},
        'MANDATORY_CONSTRAINT_INVENTION':'Zero scored executed hard-operand mismatch contexts under frozen masks; source projection tampering rejected. Not universal semantic correctness.',
        'SMART_MODE_STATUS':'Disabled; compatibility regressions prevent qualification.','EXACT_MODE_STATUS':'Established bounded native delegation retained.',
        'PUBLIC_LIBRARY_STATUS':'Read-only native functions pass; real JWT/membership unverified.','PRIVATE_LIBRARY_STATUS':'Read-only own-book/outsider fixtures pass; actual authority mocked.',
        'PRIVATE_GLOBAL_INDEPENDENCE':'40 local cases cover institution-owned unlinked books with global empty/inaccessible; no global reads in those fixtures.',
        'NATIVE_CHOICE_CONTRACT':'PARTIAL: actual correction_apply works, correction_keep safely rejects422; raw query >150 rejected by existing schema; source-span completion is a pure draft only.',
        'LIVE_AUTHORIZATION_VALIDATED':False,'SEMANTIC_RETRIEVAL_VERIFIED':'Fixture-only topic/filter transport; actual embeddings/ranking relevance N/A.',
        'PARSER_LATENCY':{'population':'Exposed C5ER150, serial150 and four-worker150 calls','recorded':perf['after'],'comparison':perf['before'],'SLO':'Not agreed; no operational PASS.'},
        'FULL_SEARCH_LATENCY':{'status':'N/A','reason':'No live Mongo/vector/API run.'},'STAGING_READINESS':'BLOCKED','PRODUCTION_READINESS':'BLOCKED',
        'PRODUCTION_PARSER_CHANGED':False,'ACTIVE_C4_POLICY_CHANGED':False,'MONGO_MUTATIONS':0,'HELDOUT_EVALUATIONS':0,
        'HISTORICAL_EVIDENCE_PRESERVED':{'protected_union_verified':len(pre['protected_files']),'parent_protected_entries':2450,'original_production_entries':462,'changed':0},
        'REMAINING_BLOCKERS':['76 broad regression assertions fail; not all are cosmetic.','Native edit/source recompilation, correction_keep and accepted session compatibility.','Arbitrary natural-language completeness remains unproven.','No fresh independent qualification.','Real JWT/Mongo durability/vector relevance/current health and agreed staging SLO unavailable.'],
        'NEXT_AUTHORIZED_ACTION':'Resolve the recorded source-role/coverage and native edit recompilation failures in a disabled revision; rerun compatibility gates, then freeze code before new independent authoring. No Mongo writes or deployment.'}
    qa={'required_fields':required,'development_metrics':metrics,'broad_tests':suite.attrib,'focused_passed':len(focused),'failed_assertions':len(failed),
        'read_only_retrieval_cases':48,'read_only_choice_projection_cases':4,'edit_boundary_checks':7,'fresh_acceptance_attempts':0,'new_model_calls':0,'production_activation':False,
        'candidate_snapshot_kind':'Immutable engineering record; NOT an acceptance-ready freeze.','at_utc':datetime.now(timezone.utc).isoformat()}
    write('final_qa.json',qa)
    table='| Exposed population | Typed | Execution |\n|---|---:|---:|\n'
    for k,m in metrics.items():table+='| '+k+' | '+str(m['typed_accuracy']['numerator'])+'/'+str(m['typed_accuracy']['denominator'])+' | '+str(m['execution_accuracy']['numerator'])+'/'+str(m['execution_accuracy']['denominator'])+' |\n'
    bodies=[
      ('root_cause_matrix','All25 prior false executions,18 missed valid contexts and58 typed mismatches are included in '+link(R/(P+'root_cause_matrix.json'))+'. It preserves clauses, expected/actual operands, masks, semantic residue and IR. Runtime imports no gold/case identifiers. Baseline predictions and gold remain unchanged.'),
      ('structural_families','The prior30 families were grouped independently of their five scope variants. Confirmed shared paths: domain/operator loss, entity polarity inversion, negative facet invention, quoted canonical bypass, optional-number decision carryover, metalinguistic assignment versus missing slots, language copula extraction and unsupported aggregate relationships. See unique_families in the root matrix; repeated scope rows are not independent causes.'),
      ('source_contract','Internal immutable Requirement, QueryIR, Proof and State types: '+link(C/'contract.py')+'. Each requested atom stores source/clause spans, field, operator, value, modality, polarity, support/state, representation and provenance. NOT_REQUESTED is distinguished by explicit absent-field inventory. Trusted controls are separate; text never selects scope. Complete arbitrary-language interpretation is not claimed.'),
      ('typed_IR','SMART compilation starts with an empty native QueryPlan. The front end owns modality/relationships/polarity before scalar proposals; pure grammar proposes evidence; one IR compiler projects supported resolved mandatory fields. The pure proof replays projection and rejects mutations. '+link(C/'parser.py')+' and '+link(C/'proof.py')+'. Source contracts survive decision reset; missing SMART proof rejects execution.'),
      ('missing_and_completion','States distinguish supplied, empty, omitted, placeholder, ambiguous, contradictory and unsupported. Partial operands containing unquoted placeholder syntax cannot execute. Literal quoted content stays opaque, creating some historical wire/interpretation disagreements. Pure source-span draft: '+link(C/'completion.py')+'. It checks owner/login/library/workspace, parser/mode, query digest, base version, expiry/used status, source owner and untouched projection. It does not implement actual one-use CAS or authentication.'),
      ('negative_ownership','Negative domain is assigned before positive author/title/facet grammars. Modifier ordering is compositional within the bounded domain lexer. Subject/format/text exclusions retain separate native fields; unsupported bibliographic/unknown negative fields block. Source word boundaries remain native. Tests cover16 operator/modifier combinations and Marsh/ar; finite coverage does not establish arbitrary-language understanding.'),
      ('fallback_audit',link(R/(P+'fallback_audit.json'))+' classifies each inherited path. Unsafe SMART hard-state and decision copying is removed at construction. Empty-vocabulary semantic/intent fallback remains semantically lossy and is explicitly limited to soft outputs. Old semantic inventory supplies typed evidence only; its decisions and hard state are discarded.'),
      ('execution_proof','validate_ir is pure: validates source/clause spans, state/support, numeric re-recognition, canonical resolution facts, entity/format/negative evidence, schema, and projection reconstructed from IR plus trusted controls. Contradiction > incomplete > ambiguous > unsupported. The proof verifies represented requirements; it cannot prove that every arbitrary utterance was correctly extracted. Corpus-free tampering tests and decision-reset audit pass.'),
      ('implementation_inventory',link(R/(P+'source_inventory.json'))+' provides actual source hashes, symbols and lines. The candidate is isolated under '+str(C)+'. No active production parser, C4 or authorization file changed. Failed attempts remain as separate XML, predictions and source snapshots.'),
      ('metamorphic_tests',str(len(focused))+'/'+str(len(focused))+' focused tests pass. Broad suite: '+str(int(suite.attrib['tests'])-int(suite.attrib['failures']))+'/'+suite.attrib['tests']+' pass; '+suite.attrib['failures']+' fail. Complete failures: '+link(R/(P+'regression_failures.json'))+'. These include behavioral/contract failures, so this is not validated development readiness. Gold and inherited assertions were not altered.'),
      ('development_scoring',table+'\nAll1184 contexts are exposed development material. False execution is0/394 C5C,0/60 C5E and0/100 for each150 cohort; missed valid execution is0/250,0/30 and0/50 respectively. Scored hard operand mismatches are zero among executed positives under frozen masks. Strict semantic strings, intent, source metadata and broader grammar failures remain and are not equated with safety accuracy.'),
      ('independent_validation','NOT RUN: no new acceptance population or primary capture was started. The user requires completed repairs/regression evidence before acceptance. Broad compatibility and native edit gates fail, so a fresh acceptance population was not consumed. All previous150-case populations are exposed, never credited as fresh. A later qualified revision must freeze source before independent authoring/review and use the unchanged sealed structural auditor without revealing protected content.'),
      ('operand_correctness','Projection replay rejects added author, changed number, forged category and wrong format. Recorded exposed scoring has zero executed hard-field mismatch contexts. This is scoped to frozen scalar masks; unadapted structured semantics, sort semantics and complete-language meaning are not proven. Full C5C failure/scored observations remain separate and immutable.'),
      ('library_fixtures','48/48 read-only retrieval cases pass (40 local+8 global), plus4 native choice projections. Source-extracted actual native functions use mock authority and collections. Institution-owned unlinked books work with global empty/inaccessible, outsiders are concealed by fixture guards and foreign rows excluded. Topic transport/pagination/serialization pass with a fixed-ID semantic provider; no actual relevance or live authorization claim. '+link(R/(P+'certified_retrieval_contracts_final.json'))),
      ('choice_integration','Actual ChoiceRequest.query limit is150 raw characters; parser/session500. UUID references still require exact raw-query equality, so no reference-only bypass is supported. No truncation/schema change occurred. Pure completion prototype performs only a bound draft; actual issuance/CAS durability requires approved integration. Native correction_keep now rejects422 because removing a hard field without recompiling its IR is unproven; this is a compatibility blocker, not a passing native-edit claim. '+link(R/(P+'edit_audit.json'))),
      ('profiling','Matched exposed C5ER150 workload,300 calls per architecture: final serial p50 '+str(round(perf['after']['serial']['p50_ms'],2))+'ms, p95 '+str(round(perf['after']['serial']['p95_ms'],2))+'ms; four-worker p95 '+str(round(perf['after']['four_workers']['p95_ms'],2))+'ms, max '+str(round(perf['after']['four_workers']['max_ms'],2))+'ms. Errors0/300; serial/concurrent plan hashes150/150 equal. Architecture output hashes need not equal V3. Profile: '+link(R/(P+'recorded_profile_after.txt'))+'. No safety check was removed to improve timings; no further optimization without confirmed bottleneck. Shared host/order limits inference; no agreed SLO.'),
      ('staging_prerequisites','All Mongo writes remain prohibited, including disposable databases. Future explicit authorization must name a unique disposable namespace and restricted credentials, permit index startup writes and exact cleanup, and cover real JWT/current membership changes, patron/staff/outsider concealment, one-use choice/CAS/expiry/recovery,500-character binding, typed completion, actual vectors with paired generations and independently labeled relevance, concurrent load, agreed SLO and rollback. Current resident health was not polled; last historical observation remains STALE/degraded, baseline_verified=False. No catalog reduction or HNSW/KG rebuild occurred.'),
      ('preservation','Before implementation verified parent2450 protected entries,44 candidate/contract entries and338 evidence entries. Union protected for this phase='+str(len(pre['protected_files']))+', including462 original production entries. All byte hashes checked again at completion. Final evidence manifest and verification are written separately; no destructive reset/clean or historical edits.'),
      ('final_QA',table+'\nFINAL=PARTIAL. Production/staging remain BLOCKED. Full required fields: '+link(R/(P+'final_qa.json'))+'. No fresh evaluation or deployment. Broad failures and native edit incompatibility remain material.'),
      ('architecture_next_action','The selected deterministic proof compiler removes unsafe fallback authority but does not establish arbitrary supported-language completeness. Do not keep adding phrase exceptions to chase exposed scores. Next: resolve source-role/modal partition and native edit recompilation contract failures, then assess genuinely new syntax. A small bounded extractor is justified only as a separate disabled sandbox proposal if maintained deterministic coverage remains insufficient. It must emit typed source spans/operators/modality/domain and explicit unknowns, with deterministic proof validation and safe clarification; model output is never authority.\n\nNo model/runtime is selected or enabled. Suggested sandbox labeling design (proposal, not performed): independently review2000 diverse new contexts and a separately sealed new500-context test population, with scope/polarity/omission adversarial pairs. Do not reuse historical protected holdout. Fine-tuning, labels and model licensing/security need separate review. Runtime, training time, monetary cost and latency are UNMEASURED; do not fabricate them. Cost accounting must record calls × input/output tokens × chosen provider tariff, or measured GPU/CPU-hours × deployment rate plus labeling/review hours. A1-billion-parameter4-bit weight payload has a mathematical floor of0.5GB before runtime/KV/buffers, not a product memory or speed claim. Bound input500characters and output schema/token budget, benchmark cold/warm p50/p95/concurrency and fault behavior before choosing any component. Extraction can still omit meaning, so span validity alone is not semantic correctness. Qwen was not added. Production activation and all staging operations remain separately unauthorized.')]
    for i,(title,body) in enumerate(bodies,1):doc(i,title,body)
    assert not subprocess.check_output(['git','diff','--name-only'],text=True).strip() and not subprocess.check_output(['git','diff','--cached','--name-only'],text=True).strip()
    files={str(p):sha(p) for p in R.glob(P+'*') if p.is_file() and p.name not in [P+'freeze_manifest.json',P+'freeze_verification.json']}
    files.update({str(p):sha(p) for p in Path('scripts').glob(P+'*.py')})
    for root in [C,*Path('scratch').glob('search_proof4*')]:
        if root.is_dir():files.update({str(p):sha(p) for p in root.rglob('*') if p.is_file() and p.suffix in ['.py','.txt'] and '__pycache__' not in p.parts})
    write('freeze_manifest.json',{'kind':'Immutable engineering record, not acceptance-ready freeze','candidate_id':required['CANDIDATE_ID'],'files':files,'FINAL':'PARTIAL','activated':False})
    assert all(sha(p)==h for p,h in files.items()) and all(sha(p)==h for p,h in pre['protected_files'].items())
    write('freeze_verification.json',{'status':'PASS','protected_union_verified':len(pre['protected_files']),'production_entries_verified':462,'new_files':len(files),'changed':0,'manifest_sha256':sha(R/(P+'freeze_manifest.json')),'Mongo_mutations':0,'heldout_evaluations':0,'fresh_acceptance_attempts':0,'tracked_changes':0,'activated':False})
    print(json.dumps({'FINAL':'PARTIAL','focused':len(focused),'broad_tests':suite.attrib['tests'],'failures':len(failed),'frozen_files':len(files),'protected':len(pre['protected_files'])}))
if __name__=='__main__':main()
